export const EVENT_BY_ID = Object.fromEntries(EVENTS.map((e) => [e.id, e]));

/**
 * World Athletics points for a result. Returns an integer >= 0, or null if the
 * event/gender is unavailable or the result is out of the tables scoring range.
 * @param {string} eventId  key from EVENTS
 * @param {"men"|"women"} gender
 * @param {number} x  seconds (time) | metres (distance) | points (combined)
 */
export function pointsFor(eventId, gender, x) {
  const table = COEFFS[gender];
  if (!table || !table[eventId] || !(x > 0)) return null;
  const [a, b, c] = table[eventId];
  const pts = Math.floor(a * x * x + b * x + c);
  return pts > 0 ? pts : null;
}
